import java.math.BigDecimal;
import java.math.RoundingMode;

/**
 * 费用计算工具类（纯 Java，无外部依赖）。
 *
 * 配送费规则：
 *   - itemCount == 0 返回 0
 *   - itemCount > 0 且 amount > 200 返回 0
 *   - 其余（含 amount == 200）返回 12
 *
 * 服务费规则：
 *   - amount == 0 返回 0
 *   - 0 < amount <= 100 返回 2
 *   - amount > 100 返回 5
 *
 * 金额单位：元。返回值统一保留 2 位小数，不修改输入对象。
 */
public final class FeeCalculator {

    private static final BigDecimal DELIVERY_FREE_THRESHOLD = new BigDecimal("200");
    private static final BigDecimal DELIVERY_BASE_FEE = new BigDecimal("12");
    private static final BigDecimal SERVICE_FREE_THRESHOLD = BigDecimal.ZERO;
    private static final BigDecimal SERVICE_LOW_THRESHOLD = new BigDecimal("100");
    private static final BigDecimal SERVICE_LOW_FEE = new BigDecimal("2");
    private static final BigDecimal SERVICE_HIGH_FEE = new BigDecimal("5");
    private static final int SCALE = 2;

    private FeeCalculator() {
        // 工具类，禁止实例化
    }

    /**
     * 计算配送费。
     *
     * @param amount    订单金额（元），不能为 null 且必须 >= 0
     * @param itemCount 商品件数，不能小于 0
     * @return 配送费，保留 2 位小数
     * @throws IllegalArgumentException 当 amount 为 null、amount < 0 或 itemCount < 0
     */
    public static BigDecimal deliveryFee(BigDecimal amount, int itemCount) {
        // 配送费业务对象校验：金额 + 件数
        if (amount == null) {
            throw new IllegalArgumentException("配送费计算失败：订单金额不能为 null");
        }
        if (amount.compareTo(BigDecimal.ZERO) < 0) {
            throw new IllegalArgumentException("配送费计算失败：订单金额不能为负数，实际为 " + amount);
        }
        if (itemCount < 0) {
            throw new IllegalArgumentException("配送费计算失败：商品件数不能为负数，实际为 " + itemCount);
        }

        BigDecimal fee;
        if (itemCount == 0) {
            fee = BigDecimal.ZERO;
        } else if (amount.compareTo(DELIVERY_FREE_THRESHOLD) > 0) {
            // 严格大于 200 才免配送；amount == 200 不免
            fee = BigDecimal.ZERO;
        } else {
            fee = DELIVERY_BASE_FEE;
        }
        return fee.setScale(SCALE, RoundingMode.HALF_UP);
    }

    /**
     * 计算服务费。
     *
     * @param amount 订单金额（元），不能为 null 且必须 >= 0
     * @return 服务费，保留 2 位小数
     * @throws IllegalArgumentException 当 amount 为 null 或 amount < 0
     */
    public static BigDecimal serviceFee(BigDecimal amount) {
        // 服务费业务对象校验：仅金额，独立于配送费
        if (amount == null) {
            throw new IllegalArgumentException("服务费计算失败：订单金额不能为 null");
        }
        if (amount.compareTo(BigDecimal.ZERO) < 0) {
            throw new IllegalArgumentException("服务费计算失败：订单金额不能为负数，实际为 " + amount);
        }

        BigDecimal fee;
        if (amount.compareTo(SERVICE_FREE_THRESHOLD) == 0) {
            fee = BigDecimal.ZERO;
        } else if (amount.compareTo(SERVICE_LOW_THRESHOLD) <= 0) {
            // 0 < amount <= 100
            fee = SERVICE_LOW_FEE;
        } else {
            // amount > 100
            fee = SERVICE_HIGH_FEE;
        }
        return fee.setScale(SCALE, RoundingMode.HALF_UP);
    }
}
