import java.math.BigDecimal;

/**
 * FeeCalculator 的独立测试类，使用 main + 断言，不依赖测试框架。
 * 覆盖：负数、null、0、100、200 及阈值上下相邻金额；配送费覆盖件数 0 与 1；
 * 同时验证返回精度与输入 BigDecimal 未被修改。
 */
public class FeeCalculatorTest {

    private static int passed = 0;
    private static int failed = 0;

    public static void main(String[] args) {
        // ---------- 配送费：正常流程 ----------
        assertEquals("配送费 件数0 金额0", "0.00",
                FeeCalculator.deliveryFee(new BigDecimal("0"), 0).toPlainString());
        assertEquals("配送费 件数0 金额500", "0.00",
                FeeCalculator.deliveryFee(new BigDecimal("500"), 0).toPlainString());

        // ---------- 配送费：边界值 ----------
        assertEquals("配送费 件数1 金额0", "12.00",
                FeeCalculator.deliveryFee(new BigDecimal("0"), 1).toPlainString());
        assertEquals("配送费 件数1 金额100", "12.00",
                FeeCalculator.deliveryFee(new BigDecimal("100"), 1).toPlainString());
        assertEquals("配送费 件数1 金额199.99", "12.00",
                FeeCalculator.deliveryFee(new BigDecimal("199.99"), 1).toPlainString());
        assertEquals("配送费 件数1 金额200（恰好200不免）", "12.00",
                FeeCalculator.deliveryFee(new BigDecimal("200"), 1).toPlainString());
        assertEquals("配送费 件数1 金额200.01（严格大于200免）", "0.00",
                FeeCalculator.deliveryFee(new BigDecimal("200.01"), 1).toPlainString());
        assertEquals("配送费 件数1 金额201", "0.00",
                FeeCalculator.deliveryFee(new BigDecimal("201"), 1).toPlainString());

        // ---------- 配送费：异常流程 ----------
        assertThrows("配送费 null 金额", IllegalArgumentException.class,
                () -> FeeCalculator.deliveryFee(null, 1));
        assertThrows("配送费 负金额", IllegalArgumentException.class,
                () -> FeeCalculator.deliveryFee(new BigDecimal("-0.01"), 1));
        assertThrows("配送费 负件数", IllegalArgumentException.class,
                () -> FeeCalculator.deliveryFee(new BigDecimal("100"), -1));

        // ---------- 服务费：正常流程 ----------
        assertEquals("服务费 金额0", "0.00",
                FeeCalculator.serviceFee(new BigDecimal("0")).toPlainString());

        // ---------- 服务费：边界值 ----------
        assertEquals("服务费 金额0.01", "2.00",
                FeeCalculator.serviceFee(new BigDecimal("0.01")).toPlainString());
        assertEquals("服务费 金额100（不超过100）", "2.00",
                FeeCalculator.serviceFee(new BigDecimal("100")).toPlainString());
        assertEquals("服务费 金额100.01（严格大于100）", "5.00",
                FeeCalculator.serviceFee(new BigDecimal("100.01")).toPlainString());
        assertEquals("服务费 金额200", "5.00",
                FeeCalculator.serviceFee(new BigDecimal("200")).toPlainString());
        assertEquals("服务费 金额200.01", "5.00",
                FeeCalculator.serviceFee(new BigDecimal("200.01")).toPlainString());

        // ---------- 服务费：异常流程 ----------
        assertThrows("服务费 null 金额", IllegalArgumentException.class,
                () -> FeeCalculator.serviceFee(null));
        assertThrows("服务费 负金额", IllegalArgumentException.class,
                () -> FeeCalculator.serviceFee(new BigDecimal("-1")));

        // ---------- 返回精度 ----------
        BigDecimal delivery = FeeCalculator.deliveryFee(new BigDecimal("50"), 1);
        assertEquals("配送费 精度 scale=2", "2", String.valueOf(delivery.scale()));
        BigDecimal service = FeeCalculator.serviceFee(new BigDecimal("50"));
        assertEquals("服务费 精度 scale=2", "2", String.valueOf(service.scale()));

        // ---------- 输入 BigDecimal 未被修改 ----------
        BigDecimal input = new BigDecimal("200.005");
        String before = input.toPlainString();
        FeeCalculator.deliveryFee(input, 1);
        FeeCalculator.serviceFee(input);
        assertEquals("输入 BigDecimal 未被修改", before, input.toPlainString());

        // ---------- 汇总 ----------
        System.out.println("通过: " + passed + "，失败: " + failed);
        if (failed > 0) {
            throw new AssertionError("存在失败用例: " + failed);
        }
        System.out.println("全部测试通过。");
    }

    // ---------- 断言辅助方法 ----------

    private static void assertEquals(String name, String expected, String actual) {
        if (expected.equals(actual)) {
            passed++;
            System.out.println("[PASS] " + name + " => " + actual);
        } else {
            failed++;
            System.out.println("[FAIL] " + name + " 期望=" + expected + " 实际=" + actual);
        }
    }

    private static void assertThrows(String name, Class<? extends Throwable> expectedType, Runnable action) {
        try {
            action.run();
            failed++;
            System.out.println("[FAIL] " + name + " 期望抛出 " + expectedType.getSimpleName() + "，但未抛出");
        } catch (Throwable t) {
            if (expectedType.isInstance(t)) {
                passed++;
                System.out.println("[PASS] " + name + " => 抛出 " + t.getClass().getSimpleName() + ": " + t.getMessage());
            } else {
                failed++;
                System.out.println("[FAIL] " + name + " 期望 " + expectedType.getSimpleName()
                        + "，实际 " + t.getClass().getSimpleName());
            }
        }
    }
}
